source='''from collections import Counter
def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    remaining = Counter({v: n*4 for v,n in counts.items()})
    for row in grid:
        remaining.subtract(row)
    out = [[None for _ in range(2*w)] for _ in range(2*h)]
    for r in range(h):
        for c in range(w):
            out[r][c] = grid[r][c]
    pool = []
    for v, n in sorted(remaining.items()):
        pool.extend([v]*n)
    it = iter(pool)
    for r in range(2*h):
        for c in range(2*w):
            if out[r][c] is None:
                out[r][c] = next(it)
    return out
'''
